,\"isRootBlock\":false,\"style\":{\"typography\":{\"letterSpacing\":\"5px\"}},\"textColor\":\"ast-global-color-1\",\"responsiveControls\":{\"lg\":{\"style\":{\"typography\":{\"letterSpacing\":\"5px\"}}},\"md\":{\"style\":{\"typography\":{\"letterSpacing\":\"5px\",\"lineHeight\":\"1.3em\",\"fontSize\":\"35px\"}}},\"sm\":{\"style\":{\"typography\":{\"letterSpacing\":\"5px\",\"lineHeight\":\"1.3em\",\"textAlign\":\"center\",\"fontSize\":\"30px\"}}}},\"spectraId\":\"spectra-cta-title-68c3871a\"} /-->\n\n<!-- wp:spectra/content {\"tagName\":\"p\",\"text\":\"Have any questions? We are always open to discussing your business, new projects, creative opportunities, and how we can help you.\",\"isRootBlock\":false,\"style\":{\"typography\":{\"letterSpacing\":\"0px\",\"lineHeight\":\"1.5em\",\"textAlign\":\"center\"}},\"textColor\":\"ast-global-color-3\",\"fontSize\":\"14px\",\"responsiveControls\":{\"lg\":{\"fontSize\":\"14px\",\"style\":{\"typography\":{\"letterSpacing\":\"0px\",\"lineHeight\":\"1.5em\",\"textAlign\":\"center\"}}},\"md\":{\"style\":{\"typography\":{\"letterSpacing\":\"0px\",\"lineHeight\":\"1.5em\",\"textAlign\":\"center\"}}},\"sm\":{\"style\":{\"typography\":{\"letterSpacing\":\"0px\",\"lineHeight\":\"1.5em\",\"textAlign\":\"center\"}}}},\"spectraId\":\"spectra-cta-desc-68c3871a\"} /-->\n<!-- /wp:spectra/container -->\n\n<!-- wp:spectra/buttons {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"},\"style\":{\"spacing\":{\"blockGap\":\"15px\"}},\"responsiveControls\":{\"lg\":{\"style\":{\"spacing\":{\"blockGap\":\"15px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}},\"md\":{\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"},\"style\":{\"spacing\":{\"blockGap\":\"15px\"}}},\"sm\":{\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"},\"style\":{\"spacing\":{\"blockGap\":\"15px\"}}}},\"spectraId\":\"spectra-cta-buttons-68c3871a\"} -->\n<!-- wp:spectra/button {\"text\":\"GET IN TOUCH\",\"linkURL\":\"#\",\"linkRel\":[null,null,null],\"linkTar