(2154,	1,	'2026-10-04 18:11:15',	'2026-10-04 18:11:15',	'{\n    \"custom_css[nhom-3-tu-lam]\": {\n        \"value\": \"/* \\u00c9p to\\u00e0n b\\u1ed9 trang web nh\\u1eadn font Lora, m\\u00e0u kem s\\u1eefa v\\u00e0 ch\\u1eef n\\u00e2u \\u1ea5m */\\nhtml, body {\\n    background-color: #fffaf0 !important;\\n    color: #4a3b32 !important;\\n    font-family: \'Lora\', Georgia, serif !important;\\n    line-height: 1.8;\\n    margin: 0;\\n    padding: 0;\\n}\\n\\nheader.site-header {\\n    background-color: #f5ebe0 !important;\\n    padding: 30px 20px;\\n    text-align: center;\\n    border-bottom: 3px double #d5c7b8;\\n}\\n\\nheader.site-header h1, \\nheader.site-header p {\\n    color: #4a3b32 !important;\\n    margin: 0 0 10px 0;\\n}\\n\\n.news-portal-container {\\n    max-width: 1240px;\\n    margin: 25px auto;\\n    padding: 0 20px;\\n}\\n\\n.portal-top-bar {\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    background: #f5ebe0 !important;\\n    padding: 10px 20px;\\n    border-radius: 6px;\\n    margin-bottom: 20px;\\n    border: 1px solid #e3d5ca;\\n}\\n\\n.language-switcher a {\\n    color: #7f6e63 !important;\\n    text-decoration: none;\\n}\\n\\n.language-switcher .lang-active {\\n    font-weight: bold;\\n    color: #4a3b32 !important;\\n}\\n\\n.search-form {\\n    display: flex;\\n    gap: 8px;\\n}\\n\\n.search-field {\\n    padding: 6px 12px;\\n    border: 1px solid #d5c7b8;\\n    border-radius: 4px;\\n    background: #fffaf0;\\n    color: #4a3b32;\\n    font-family: \'Lora\', serif;\\n    outline: none;\\n}\\n\\n.search-submit {\\n    background: #4a3b32;\\n    color: #fffaf0;\\n    border: none;\\n    padding: 6px 14px;\\n    border-radius: 4px;\\n    cursor: pointer;\\n    font-family: \'Lora\', serif;\\n}\\n\\n.news-category-bar {\\n    display: flex;\\n    justify-content: center;\\n    flex-wrap: wrap;\\n    gap: 15px;\\n    background: #f5ebe0 !important;\\n    padding: 15px;\\n    border-radius: 8px;\\n    margin-bottom: 30px;\\n    border-bottom: 3px double #d5c7b8;\\n}\\n\\n.news-category-bar .cat-item {\\n    font-weight: bold;\\n    color: #4a3b32 !important;\\n    padding: 6px 14px;\\n    background: #fffaf0;\\n    border-radius: 4px;\\n    border: 1px solid #e3d5ca;\\n    text-decoration: none;\\n}\\n\\n.news-category-bar .cat-item:hover {\\n    background: #4a3b32;\\n    color: #fffaf0 !important;\\n}\\n\\n.portal-grid {\\n    display: grid;\\n    grid-template-columns: 1fr 1.8fr 1fr;\\n    gap: 25px;\\n}\\n\\n.section-title {\\n    font-size: 16px;\\n    font-weight: bold;\\n    border-bottom: 2px solid #d5c7b8;\\n    padding-bottom: 8px;\\n    margin-bottom: 15px;\\n    color: #4a3b32 !important;\\n}\\n\\n.news-card-mini {\\n    display: flex;\\n    gap: 12px;\\n    background: #ffffff !important;\\n    padding: 12px;\\n    border-radius: 6px;\\n    margin-bottom: 15px;\\n    border: 1px solid #e3d5ca !important;\\n}\\n\\n.mini-thumb img {\\n    width: 70px;\\n    height: 70px;\\n    object-fit: cover;\\n    border-radius: 4px;\\n}\\n\\n.mini-content h4 {\\n    font-size: 14px;\\n    margin: 0 0 6px 0;\\n}\\n\\n.mini-content h4 a {\\n    color: #4a3b32 !important;\\n    text-decoration: none;\\n}\\n\\n.meta-info {\\n    font-size: 12px;\\n    color: #7f6e63;\\n}\\n\\n.featured-lead-article {\\n    background: #ffffff !important;\\n    padding: 30px !important;\\n    border-radius: 8px;\\n    border: 1px solid #e3d5ca !important;\\n}\\n\\n.lead-thumb img {\\n    width: 100%;\\n    height: auto;\\n    border-radius: 6px;\\n    margin-bottom: 15px;\\n}\\n\\n.featured-lead-article h2 a {\\n    color: #4a3b32 !important;\\n    text-decoration: none;\\n    font-size: 24px;\\n}\\n\\n.lead-meta {\\n    font-size: 13px;\\n    color: #7f6e63;\\n    margin-bottom: 12px;\\n}\\n\\n.article-footer-actions {\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    margin-top: 20px;\\n    padding-top: 15px;\\n    border-top: 1px solid #f0e6dd;\\n}\\n\\n.read-more-link {\\n    font-weight: bold;\\n    color: #4a3b32 !important;\\n    text-decoration: none;\\n}\\n\\n.share-buttons {\\n    display: flex;\\n    gap: 8px;\\n    font-size: 14px;\\n    color: #7f6e63;\\n}\\n\\n.news-stream-list {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 15px;\\n}\\n\\n.stream-item {\\n    background: #ffffff !important;\\n    padding: 15px;\\n    border-radius: 6px;\\n    border: 1px solid #e3d5ca !important;\\n}\\n\\n.stream-item h4 {\\n    font-size: 15px;\\n    margin: 0 0 5px 0;\\n}\\n\\n.stream-item h4 a {\\n    color: #4a3b32 !important;\\n    text-decoration: none;\\n}\\n\\n.literary-quote-box {\\n    background: #f5ebe0 !important;\\n    padding: 20px;\\n    border-radius: 6px;\\n    border: 1px solid #d5c7b8;\\n    margin-top: 20px;\\n    text-align: center;\\n}\\n\\n.literary-quote-box h4 {\\n    margin-top: 0;\\n    color: #4a3b32 !important;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-10-04 18:10:52\"\n    }\n}',	'',	'',	'trash',	'closed',	'closed',	'',	'3ee00141-2481-4a20-9250-88db7ad3b1f9',	'',	'',	'2026-10-04 18:11:15',	'2026-10-04 18:11:15',	'',	0,	'http://nhom3-news-blog.local/?p=2154',	0,	'customize_changeset',	'',	0),
